//! 模拟执行的项目级契约
//!
//! 调用方 (语言服务) 会把模拟诊断与常规诊断**按场景对齐** (见
//! `webgal-language-service` 的 `diagnose_project`), 因此 [`simulate`] 必须对每个场景
//! 都给出一条记录, 没有诊断时给空数组 —— 包括缺少入口场景、一条语句都没执行的情况.

use std::collections::HashMap;

use webgal_language_core::{element::AnimationList, resource::Config, sentence::Scene};
use webgal_simulate::{ProjectView, simulate};

/// 测试项目视图
struct TestProject {
    config: Config,
    scenes: HashMap<String, Scene>,
}

impl<'a> ProjectView<'a> for &'a TestProject {
    fn get_config(&self) -> &'a Config {
        &self.config
    }

    fn get_scene(&self, path: &str) -> Option<&'a Scene> {
        self.scenes.get(path)
    }

    fn iter_scenes(&self) -> impl Iterator<Item = (String, &'a Scene)> + Send {
        self.scenes
            .iter()
            .map(|(path, scene)| (path.clone(), scene))
    }

    fn get_animation(&self, _name: &str) -> Option<&'a AnimationList> {
        None
    }
}

/// 构建测试项目
fn project(scenes: &[(&str, &str)]) -> TestProject {
    TestProject {
        config: Config::from_str(""),
        scenes: scenes
            .iter()
            .map(|&(path, content)| (path.to_string(), Scene::from_str(content)))
            .collect(),
    }
}

/// 模拟诊断的场景路径 (排序后返回, 消除哈希序)
fn diagnosed_paths(project: &TestProject) -> Vec<String> {
    let mut paths: Vec<_> = simulate(project)
        .into_iter()
        .map(|(path, _)| path)
        .collect();
    paths.sort();
    paths
}

#[test]
fn reports_placeholder_for_every_scene() {
    let project = project(&[
        ("start.txt", "wait:100;"),
        ("chapter_01/part_01.txt", "wait:200;"),
    ]);

    assert_eq!(
        diagnosed_paths(&project),
        vec![
            "chapter_01/part_01.txt".to_string(),
            "start.txt".to_string()
        ]
    );
}

#[test]
fn reports_placeholder_without_entry_scene() {
    // 缺少入口场景: 没有语句可执行, 但仍要为每个场景给出占位
    let project = project(&[
        ("probe.txt", "wait:100;"),
        ("chapter_01/part_01.txt", "wait:200;"),
    ]);

    assert_eq!(
        diagnosed_paths(&project),
        vec![
            "chapter_01/part_01.txt".to_string(),
            "probe.txt".to_string()
        ]
    );

    // 一条语句都没跑过, 不能报死代码之类的误报
    assert!(
        simulate(&project)
            .into_iter()
            .all(|(_, diagnostics)| diagnostics.is_empty())
    );
}
